const $=s=>document.querySelector(s),main=$('#vocabMain'),dialog=$('#wordDialog'),content=$('#wordContent');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').toLowerCase().replace(/\s/g,'');
let lessonView='usages',usageIndex=0,standardExampleIndex=0,trapIndex=0;const checkState=new Map();
const stages=['Hiểu','Ghép câu','Phân biệt','Luyện','Ôn'];let dataset,words=[],selected,stage=0,query='',filter='all',routeName='words',session=[],pos=0,isReview=false,chosen=null,revealed=false,heard=false,listenShown=false,moreIndex=0,exampleIndex=0,quizMode='choice',returnFocus=null;let toastTimer;const drafts=new Map();
function notify(text){$('#vocabToast').textContent=text;$('#vocabToast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#vocabToast').classList.remove('visible'),5000)}
let storage;try{storage=window.localStorage}catch{storage={getItem(){throw Error()},setItem(){throw Error()}}}
const progress=createProgress(storage,notify);let conversationController=null,practiceSerial=0,practiceIds=[];
let courseLevel=1;try{const saved=Number(storage.getItem('hanzi-course-level-v7'));if([1,2,3].includes(saved))courseLevel=saved}catch{}
let lessonPage=0,display={hanzi:true,meaning:true},audioOptions={mode:'quick',scope:'lesson',lesson:0,from:1,to:10,rate:.9,repeat:false,awake:true};
try{const pref=JSON.parse(storage.getItem('hanzi-viet-display-v5')||'null');if(pref){for(const key of Object.keys(display))if(typeof pref[key]==='boolean')display[key]=pref[key];if(!Object.values(display).some(Boolean))display.hanzi=true}}catch{}
function saveDisplay(){try{storage.setItem('hanzi-viet-display-v5',JSON.stringify(display))}catch{notify('Không lưu được tùy chọn hiển thị.')}}
function lessonWords(){const list=filtered(),pages=coursePages(dataset,list);lessonPage=Math.min(Math.max(0,lessonPage),Math.max(0,pages.length-1));return pages[lessonPage]?.words||[]}
function courseOrdinal(word){return words.findIndex(w=>w.id===word.id)+1}
function lessonLabel(lesson){const title=lesson.title&&!/^HSK\s+\d+\s+·\s+Bài\s+\d+$/u.test(lesson.title)?` · ${lesson.title}`:'';return `HSK ${lesson.level} · Bài ${lesson.number}${title}`}
let wakeLock=null,wakePending=false;
async function releaseWake(){const lock=wakeLock;wakeLock=null;if(lock)try{await lock.release()}catch{}}
async function keepAwake(){if(wakePending||wakeLock||!audioOptions.awake||player.state.status!=='playing'||document.visibilityState!=='visible')return;if(!navigator.wakeLock){if($('#wakeStatus'))$('#wakeStatus').textContent='Thiết bị chưa hỗ trợ giữ màn hình sáng.';return}wakePending=true;try{const lock=await navigator.wakeLock.request('screen');if(player.state.status==='playing'&&audioOptions.awake){wakeLock=lock;lock.addEventListener('release',()=>{if(wakeLock===lock)wakeLock=null;updatePlayerUI(player.state)})}else await lock.release()}catch{if($('#wakeStatus'))$('#wakeStatus').textContent='Chưa giữ được màn hình sáng. Hãy kiểm tra chế độ tiết kiệm pin.'}finally{wakePending=false}}
const voicePreferences={'zh-CN':'','vi-VN':''};
try{const saved=JSON.parse(storage.getItem('hanzi-viet-voices-v51')||'null');if(saved)for(const lang of Object.keys(voicePreferences))if(typeof saved[lang]==='string')voicePreferences[lang]=saved[lang]}catch{}
const player=createAudioPlayer({preferredVoice:lang=>voicePreferences[lang],synth:window.speechSynthesis,makeUtterance:t=>new SpeechSynthesisUtterance(t),changed:s=>{updatePlayerUI(s);if(s.status==='playing')keepAwake();else releaseWake()}});

const oneShot=createAudioPlayer({synth:window.speechSynthesis,makeUtterance:t=>new SpeechSynthesisUtterance(t),preferredVoice:lang=>voicePreferences[lang],changed:s=>{
 const box=$('#voiceTestStatus');
 if(s.status==='playing'&&box)box.textContent='Đang thử '+(s.item?.lang==='vi-VN'?'giọng Việt':'giọng Trung')+'…';
 if(s.status==='error'){const message=speechErrorMessage(s.error);if(box)box.textContent=message;notify(message);if($('#listenStatus'))$('#listenStatus').textContent=message;}
 if(s.status==='completed'){if(box)box.textContent='Bộ đọc đã báo phát xong câu thử. Nếu bạn không nghe thấy, hãy kiểm tra âm lượng và tai nghe.';if(stage===3&&quizMode==='listen'){heard=true;if($('#listenStatus'))$('#listenStatus').textContent='Đã phát xong. Hãy tự nhớ nghĩa trước khi xem câu.'}}
}});
function stop(){player.stop();oneShot.stop();conversationController?.stop()}
function speak(text,slow=false,lang='zh-CN'){
 stop();oneShot.load([{text,lang,word:text,wordId:'test',wordIndex:0,label:'Thử giọng'}]);oneShot.setRate(slow?.65:audioOptions.rate);oneShot.play();
}
const hanzi=(s,target=selected?.hanzi)=>{const text=String(s??''),targets=Array.isArray(target)?target:target?[target]:[];let offset=0;const spans=[];for(const t of targets){let at=text.indexOf(t);while(t&&at>=0){spans.push([at,at+t.length]);at=text.indexOf(t,at+t.length)}}return `<span class="zh" lang="zh-CN">${[...text].map(ch=>{const mark=spans.some(([a,b])=>offset>=a&&offset<b);offset+=ch.length;const item=/\p{Script=Han}/u.test(ch)?`<a class="hanzi-char" href="${hanziURL(ch)}" aria-label="Phân tích chữ ${ch}">${ch}</a>`:esc(ch);return mark?`<strong class="target-hanzi">${item}</strong>`:item}).join('')}</span>`};
function hanziURL(char){const url=new URL('./index.html',location.href);url.searchParams.set('char',char);if(selected){url.searchParams.set('word',selected.id);url.searchParams.set('step',stage)}return url.pathname+url.search;}
const rich=s=>[...String(s??'')].map(ch=>/\p{Script=Han}/u.test(ch)?`<a class="hanzi-char" lang="zh-CN" href="${hanziURL(ch)}" aria-label="Phân tích chữ ${ch}">${ch}</a>`:esc(ch)).join('');
function sentence(s){return `<div class="example-zh">${hanzi(s.zh)}</div><p class="translation">${esc(s.vi)}</p>${s.analysis?`<p class="analysis">${rich(s.analysis)}</p>`:''}<div class="audio-row"><button class="soft" data-say="${esc(s.zh)}">◖ Nghe câu</button><button class="soft" data-say="${esc(s.zh)}" data-slow="1">Nghe chậm</button></div>`}
function playLessonSegments(segments){stop();if(!segments.length){notify('Phần này chưa có audio theo mẫu mới.');return}oneShot.load(segments.map(s=>({...s,wordId:selected?.id||'section',word:selected?.hanzi||'',wordIndex:0})));oneShot.setRate(audioOptions.rate);oneShot.play();}
function coverageNotice(word){const a=auditLesson(word);if(a.ready)return '';const missing=standardSections.filter(([key])=>a.issues.some(i=>i.path===key||i.path.startsWith(key+'.')));return `<details class="content-coverage"><summary>Đang bổ sung theo mẫu 5.1–5.6</summary><p>Mục này chưa đủ mẫu mới. Phần có sẵn có thể dùng để tham khảo; chưa được coi là bài giảng hoàn chỉnh.</p><ul>${missing.map(([,label])=>`<li>${esc(label)}</li>`).join('')}</ul></details>`;}
let auditPage=0,auditLevel=1,auditQuery='',auditFilter='pending';
function auditView(){
 const ready=words.filter(w=>auditLesson(w).ready).length;
 main.innerHTML=`<section class="welcome"><span class="eyebrow">RÀ SOÁT TỪNG MỤC</span><h1>Nội dung theo mẫu của bạn.</h1><p>${ready}/${words.length} mục đủ mẫu dữ liệu 5.1–5.6. ${words.length-ready} mục còn cần bổ sung. Kiểm tra này xác nhận độ đầy đủ và liên kết, chưa thay cho rà soát ngôn ngữ của giáo viên.</p></section><section class="panel"><table class="audit-table"><thead><tr><th>Cấp</th><th>Đủ mẫu</th><th>Cần bổ sung</th></tr></thead><tbody>${[1,2,3].map(level=>{const all=words.filter(w=>w.level===level),n=all.filter(w=>auditLesson(w).ready).length;return `<tr><td>HSK ${level}</td><td>${n}</td><td>${all.length-n}</td></tr>`}).join('')}</tbody></table><p><a href="./data/vocabulary/content-audit.json" download="BAO_CAO_NOI_DUNG_V8.json">Tải báo cáo đầy đủ từng mục ↓</a></p></section><section class="audit-browser"><label for="auditSearch">Tìm chữ hoặc nghĩa</label><input id="auditSearch" type="search" value="${esc(auditQuery)}" placeholder="Tìm mục cần xem…"><div class="audit-filters"><label>Cấp<select id="auditLevel">${[1,2,3].map(level=>`<option value="${level}">HSK ${level}</option>`).join('')}</select></label><label>Trạng thái<select id="auditFilter"><option value="pending">Cần bổ sung</option><option value="ready">Đủ mẫu</option><option value="all">Tất cả</option></select></label></div><div id="auditList"></div></section>`;
 $('#auditLevel').value=auditLevel;$('#auditFilter').value=auditFilter;
 $('#auditSearch').oninput=e=>{auditQuery=e.target.value;auditPage=0;renderAuditList()};$('#auditLevel').onchange=e=>{auditLevel=Number(e.target.value);auditPage=0;renderAuditList()};$('#auditFilter').onchange=e=>{auditFilter=e.target.value;auditPage=0;renderAuditList()};renderAuditList();
}
function renderAuditList(){const records=words.filter(w=>w.level===auditLevel&&(!auditQuery||normalize(w.hanzi+' '+w.meaning).includes(normalize(auditQuery)))).map(w=>({w,a:auditLesson(w)})).filter(({a})=>auditFilter==='all'||(auditFilter==='ready'?a.ready:!a.ready)),max=Math.max(1,Math.ceil(records.length/24));auditPage=Math.min(Math.max(0,auditPage),max-1);$('#auditList').innerHTML=`<div class="card-pager"><button class="soft" data-audit-page="-1" ${auditPage===0?'disabled':''}>←</button><span>${records.length} mục · ${auditPage+1}/${max}</span><button class="soft" data-audit-page="1" ${auditPage>=max-1?'disabled':''}>→</button></div><div class="audit-cards">${records.slice(auditPage*24,auditPage*24+24).map(({w,a})=>`<button data-start="${esc(w.id)}"><b lang="zh-CN">${esc(w.hanzi)}</b><span>${esc(w.meaning)}</span><small>${a.ready?'Đủ cấu trúc mẫu mới':'Cần biên soạn thêm · '+a.completeSections+'/6 phần theo mẫu'}</small></button>`).join('')||'<p>Không có mục phù hợp.</p>'}</div>`;}
function updateDue(){$('#vocabDue').textContent=progress.due(words).length}
