function home(){
 main.innerHTML=`<section class="word-dashboard"><div class="compact-heading"><div><span class="eyebrow">TỪ VỰNG · 24 TỪ / BÀI</span><h1>Nhìn gọn. Nhớ sâu.</h1></div>${words.some(w=>w.id===progress.state.last?.id)?`<button class="resume-mini" data-start="${progress.state.last.id}" data-resume="1">Học tiếp</button>`:''}<details class="display-help"><summary>ⓘ</summary><p>${esc(dataset.description)} ${esc(dataset.editorial)} Bài đủ chia 12 từ mỗi cột. Lọc không đổi số bài gốc.</p></details></div><div class="course-levels" role="group" aria-label="Cấp độ từ vựng">${[1,2,3].map(l=>`<button data-level="${l}" aria-pressed="${courseLevel===l}" class="${courseLevel===l?'active':''}">HSK ${l}<small>${words.filter(w=>w.level===l).length} mục từ</small></button>`).join('')}</div><p class="course-caption">Bộ Hanzii · ${words.filter(w=>w.level===courseLevel&&w.status==='deep').length} mục đủ mẫu mới · ${words.filter(w=>w.level===courseLevel&&w.status==='editing').length} mục đang bổ sung · ${words.filter(w=>w.level===courseLevel&&w.status==='example').length} thẻ có ví dụ · ${words.filter(w=>w.level===courseLevel&&w.status==='catalog').length} thẻ tra cứu</p><div class="word-tools"><label class="sr-only" for="wordSearch">Tìm chữ, nghĩa hoặc phiên âm</label><input id="wordSearch" type="search" placeholder="Tìm chữ hoặc nghĩa…" value="${esc(query)}"><label class="sr-only" for="wordFilter">Lọc từ</label><select id="wordFilter"><option value="all">Tất cả</option><option value="new">Chưa học</option><option value="favorite">Yêu thích</option><option value="deep">Đủ mẫu mới</option><option value="editing">Đang bổ sung</option><option value="example">Có ví dụ</option><option value="catalog">Tra cứu</option></select></div><div class="display-switches" role="group" aria-label="Thông tin hiển thị">${[['hanzi','Hán tự'],['meaning','Nghĩa']].map(([key,label])=>`<label><input type="checkbox" data-display="${key}" ${display[key]?'checked':''}> ${label}</label>`).join('')}</div><div id="lessonBoard"></div></section>`;
 $('#wordFilter').value=filter;
 $('#wordSearch').addEventListener('input',e=>{query=e.target.value;lessonPage=0;renderList()});
 $('#wordFilter').addEventListener('change',e=>{filter=e.target.value;lessonPage=0;renderList()});renderList();
}
function renderList(){
 const list=filtered(),pages=coursePages(dataset,list),current=lessonWords(),offset=lessonPage*24,cols=columnsOf(current);
 $('#lessonBoard').innerHTML=`<div class="lesson-navigation"><button class="soft" data-lesson="-1" ${lessonPage===0?'disabled':''} aria-label="Bài trước">←</button><div><label class="sr-only" for="courseLesson">Đến bài</label><select id="courseLesson" class="lesson-title-select">${pages.length?pages.map((l,i)=>`<option value="${i}" ${i===lessonPage?'selected':''}>${esc(lessonLabel(l))}</option>`).join(''):'<option>Không có kết quả</option>'}</select><small>${current.length}/24 từ · ${pages.length} bài khớp bộ lọc</small></div><button class="soft" data-lesson="1" ${lessonPage>=pages.length-1?'disabled':''} aria-label="Bài tiếp">→</button></div>${current.length?`<div class="two-column-board">${cols.map((col,ci)=>`<div class="word-column">${col.map((w,i)=>{const ordinal=courseOrdinal(w);return `<button class="compact-word" data-start="${w.id}" aria-label="Mở từ số ${ordinal}: ${esc(w.hanzi)}"><span class="word-number" aria-label="Thứ tự từ ${ordinal}">${ordinal}</span><span class="compact-word-copy">${display.hanzi?`<b lang="zh-CN">${esc(w.hanzi)}</b>`:''}${display.meaning?`<span class="table-meaning" title="${esc(w.meaning)}">${esc(w.meaning)}</span>`:''}</span><span class="word-status" aria-hidden="true">${progress.card(w.id).favorite?'★':progress.card(w.id).learned?'✓':w.status==='deep'?'●':w.status==='editing'?'△':w.status==='example'?'◐':'○'}</span></button>`}).join('')}</div>`).join('')}</div><div class="lesson-actions"><button class="primary" data-action="studyLesson">Học bài này →</button><button class="audio-cta" data-action="handsfree">◖ Nghe rảnh tay</button><button class="practice-entry" data-action="practiceLesson">◇ Thực hành hội thoại sau bài</button></div>`:'<p class="empty">Không có từ phù hợp. Thử đổi bộ lọc hoặc từ tìm kiếm.</p>'}<p class="board-note">● Đủ mẫu mới · △ Đang bổ sung · ◐ Có ví dụ · ○ Tra cứu. Số trước từ là thứ tự trong toàn khóa; ID dữ liệu được giữ phía sau và không hiển thị trong luồng học. Trái từ trên xuống, rồi đến phải. Bài cuối cấp có thể ít hơn 24 từ.</p>`;
 const jump=$('#courseLesson');if(jump)jump.onchange=e=>{lessonPage=Number(e.target.value);renderList()};
}
function review(){const due=progress.due(words);main.innerHTML=`<section class="welcome"><span class="eyebrow">ÔN ĐỂ NHỚ LÂU</span><h1>${due.length?'Có '+due.length+' từ đang chờ.':'Một nhịp nhớ, mỗi ngày.'}</h1><p>Tự đọc, nhớ nghĩa và dùng một câu trước khi mở gợi ý.</p></section><section class="panel"><h2>${due.length?'Bắt đầu lượt ôn':'Chưa có từ đến hạn'}</h2><p>${due.length?'Từ chọn “Quên” sẽ trở lại sau khoảng 10 phút.':'Học một từ và tự đánh giá ở bước Ôn. Bạn cũng có thể luyện lại các từ đã học.'}</p>${due.length?'<button class="primary" data-action="reviewDue">Ôn từ đến hạn →</button>':''}<button class="soft" data-action="practiceLearned">Luyện lại từ đã học</button></section><button class="text-button" data-action="refresh">Kiểm tra lại đến hạn</button><section class="panel"><h2>Lịch ôn có điều chỉnh</h2><p>Đã nhớ: 1 → 3 → 7 → 14 → 30 ngày. Còn khó: 1 ngày. Quên: 10 phút và bắt đầu lại chu kỳ.</p><p class="muted">Dựa trên tự đánh giá, chưa có chấm phát âm hoặc AI chấm câu.</p></section>`}
function settings(){main.innerHTML=`<section class="welcome"><span class="eyebrow">GÓC CỦA BẠN</span><h1>Giữ lại hành trình.</h1><p>Tiến độ từ vựng lưu riêng với tiến độ Hán tự trên trình duyệt này.</p></section><section class="panel"><h2>Rà soát nội dung 5.1–5.6</h2><p>${dataset.contentAuditSummary?.ready||0}/${words.length} mục đủ cấu trúc mẫu mới. Các mục còn lại có báo phần cần bổ sung.</p><button class="soft" data-action="audit">Xem kết quả rà soát toàn bộ</button></section><section class="panel"><h2>Sao lưu từ vựng</h2><p>Xuất trước khi đổi máy hoặc đổi địa chỉ website. Bản sao có yêu thích, lịch ôn và điểm dừng.</p><div class="button-row"><button class="primary" data-action="export">↓ Xuất tiến độ</button><button class="soft" data-action="import">↑ Nhập bản sao</button></div><input id="vocabImport" type="file" accept=".json,application/json" hidden></section><details class="panel"><summary>Cách học và liên kết Hán tự</summary><p>Đi qua Hiểu → Ghép câu → Phân biệt → Luyện → Ôn. Chạm chữ Hán có gạch chân để mở phân tích, rồi bấm “Quay lại từ vựng”.</p><p>Mỗi màn hình chỉ có một phần chính. Học thêm chứa nghĩa phụ. Pinyin chỉ xuất hiện trong Giới thiệu từ mới. Bảng 24 từ chỉ bật/tắt Hán tự và nghĩa theo mẫu mới.</p><p>Giọng đọc dùng bộ đọc zh-CN trên thiết bị; chưa phải audio thu âm. Không có nhận dạng giọng nói. Câu tự viết do bạn tự đối chiếu; đáp án mẫu không phải đáp án duy nhất.</p></details><details class="panel"><summary>Nội dung, nguồn và giới hạn</summary><p>${esc(dataset.description)}</p><p>${esc(dataset.editorial)}</p><p>${esc(dataset.countNotice)}</p><p>${esc(dataset.provenance?.pronunciationNote||'')}</p>${dataset.sources.map(s=>`<p><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a></p>`).join('')}<p>Tài liệu nguồn có thể hiển thị phiên âm theo cách riêng. Bài học chi tiết giữ Pinyin trong phần giới thiệu; bảng ôn không hiện Pinyin. Kịch bản nghe không đọc Pinyin.</p></details><details class="panel"><summary>Khi gặp trục trặc</summary><p>Không nghe: tăng âm lượng và cài giọng tiếng Trung zh-CN. Một số giọng cần mạng. Đổi màn hình hoặc đóng bài sẽ dừng đọc.</p><p>Chưa phân tích được chữ: thư viện Hanzi hiện chỉ có 2.632 chữ, không bao phủ mọi chữ trong lời giảng. App sẽ thông báo rõ và cho quay lại bài.</p><p>Không lưu được: dùng trình duyệt thường và xuất bản sao; không coi chế độ ẩn danh là nơi lưu lâu dài.</p></details>`;$('#vocabImport').addEventListener('change',importFile)}
