function resetPractice(){lessonView='usages';usageIndex=0;standardExampleIndex=0;trapIndex=0;chosen=null;revealed=false;heard=false;listenShown=false;quizMode='choice';exampleIndex=0;moreIndex=0}
function openWord(id,options={}){
 const word=words.find(w=>w.id===id);if(!word){notify('Chưa có mục từ này trong khóa học.');return}
 returnFocus=document.activeElement;selected=word;stage=Number.isInteger(options.stage)&&options.stage>=0&&options.stage<5?options.stage:0;isReview=!!options.review;
 session=options.queue||lessonWords().map(w=>w.id);if(!session.includes(id))session=[id];pos=session.indexOf(id);resetPractice();if(!studySteps(word).includes(stage))stage=0;
 document.body.classList.add('word-open');if(!dialog.open)dialog.showModal();drawWord();
}
function stripLessonTechnicalMarkup(root){
 root.querySelectorAll('.course-word-source').forEach(el=>el.remove());
 root.querySelectorAll('small').forEach(el=>{if(/^Mã (ví dụ|cách dùng|câu hỏi):/.test(el.textContent.trim()))el.remove()});
 root.innerHTML=root.innerHTML.replace(/\[Từ số \d+\]\s*/g,'').replace(/\b5\.[1-6]\s*·\s*/g,'').replace(/mẫu 5\.1–5\.6/g,'mẫu bài học');
}
function drawWord(){
 stop();progress.remember(selected.id,stage);const c=progress.card(selected.id),steps=studySteps(selected),next=moveStep(selected,stage,1),lesson=dataset.lessons.find(l=>l.wordIds.includes(selected.id)),ordinal=courseOrdinal(selected);
 content.innerHTML=`<div class="lesson-top"><span>${lesson?esc(lessonLabel(lesson)):'TỪ VỰNG'} · Từ ${ordinal} · ${pos+1}/${session.length}${isReview?' · ÔN TẬP':''}</span><button data-action="close" class="round" aria-label="Đóng bài học">✕</button></div><div class="word-identity"><div><span class="eyebrow">${isReview?'TỰ NHỚ TRƯỚC KHI XEM':statusLabels[selected.status].toUpperCase()}</span><h2 lang="zh-CN">${stage===3&&quizMode==='listen'&&!listenShown?'•••':hanzi(selected.hanzi)}</h2></div><div class="identity-actions"><button class="round" data-action="favorite" aria-label="${c.favorite?'Bỏ yêu thích':'Yêu thích'}" aria-pressed="${c.favorite}">${c.favorite?'★':'☆'}</button></div></div><div class="lesson-tabs" role="tablist" aria-label="Các bước học từ">${steps.map(i=>`<button id="vstep-${i}" role="tab" aria-selected="${stage===i}" aria-controls="lessonBody" tabindex="${stage===i?0:-1}" data-step="${i}"><small>0${steps.indexOf(i)+1}</small>${stages[i]}</button>`).join('')}</div><section id="lessonBody" class="lesson-body" role="tabpanel" aria-labelledby="vstep-${stage}">${coverageNotice(selected)}${renderStage()}</section><div class="lesson-footer"><div class="step-caption"><span>${stage===3&&quizMode==='listen'&&!listenShown?'Luyện nghe':esc(selected.hanzi)} · Bước ${steps.indexOf(stage)+1}/${steps.length}</span><span>${c.learned?'✓ Đã học':'Chưa đánh dấu'}</span></div><div class="step-buttons"><button class="soft" data-action="back" ${stage===0&&pos===0?'disabled':''} aria-label="Bước trước">←</button><button class="primary" data-action="next">${stage===4?'Từ tiếp theo':'Tiếp: '+stages[next]} →</button><button class="soft" data-action="skip" ${pos===session.length-1?'disabled':''} aria-label="Bỏ qua sang từ tiếp">⇥</button></div></div>`;
 stripLessonTechnicalMarkup(content);
 const scroll=content.querySelector('.lesson-body');if(scroll)scroll.addEventListener('scroll',()=>content.classList.toggle('lesson-scrolled',scroll.scrollTop>24),{passive:true});
 content.querySelector('[data-action="close"]').focus();
}
function renderFoundation(w){
 const source=dataset.sources.find(s=>s.id===w.sourceId),example=w.examples[0],quiz=meaningQuiz(w,words);
 const note=w.status==='example'?'Thẻ có nghĩa và một câu ví dụ. Chưa có bài giảng đầy đủ về cấu trúc, đối chiếu và bẫy.':'Thẻ tra cứu nghĩa. Chưa có câu ví dụ hoặc bài giảng cách dùng; không coi việc nhớ nghĩa là đã dùng thành thạo.';
 if(stage===0)return `<p class="course-word-source">HSK ${w.level} · Mục ${w.sourceIndex} · ${statusLabels[w.status]}</p><section class="intro-word"><h3>Giới thiệu từ mới</h3>${w.intro.map((x,i)=>`${i===1?'<details><summary>Cách đọc khác · trong phần giới thiệu</summary>':''}<p class="intro-reading">${hanzi(w.hanzi)} — <span class="pinyin">${esc(x.pinyin)}</span> — ${rich(x.meaning)}</p>${x.sourcePinyin?`<details class="source-reading"><summary>Cách ghi ở nguồn Hanzii</summary><p class="intro-reading">${esc(x.sourcePinyin)}</p><p class="muted">Bài dùng cách đọc đã đối chiếu với đề cương. Khác biệt có thể liên quan thanh nhẹ, biến điệu hoặc cách ghi.</p></details>`:''}${i>0&&i===w.intro.length-1?'</details>':''}`).join('')}<button class="soft" data-say="${esc(w.audioText||w.hanzi)}">◖ Nghe ${w.audioText?'cụm gợi cách đọc':'từ'}</button></section>${example?`<h3>Trong một tình huống</h3>${sentence(example)}`:''}<details><summary>Phạm vi nội dung và nguồn</summary><p>${note}</p><p>Nghĩa Việt: ${w.meaningOrigin==='cvdict'?'CVDICT · CC BY-SA 4.0, thẻ tham khảo chưa rà soát từng nghĩa':'app biên soạn'}. Câu ví dụ, nếu có, do app biên soạn. Câu có thể dùng từ hoặc ngữ pháp ngoài bài; bản này chưa chú giải từng phần vượt cấp.</p><a href="${esc(w.membershipUrl)}" target="_blank" rel="noopener">Bộ từ Hanzii · thứ tự nguồn ${w.sourceIndex} ↗</a></details>`;
 if(stage===3)return `<h3>Tự nhớ nghĩa</h3><div class="practice-tabs"><button class="${quizMode==='choice'?'active':''}" data-mode="choice">Nhìn chữ</button><button class="${quizMode==='listen'?'active':''}" data-mode="listen">Nghe</button></div>${quizMode==='listen'?`<p>Nghe ${example?'câu':'từ'}, tự nhớ nghĩa trước khi mở đáp án.</p><button class="primary" data-action="listen">◖ Phát ${example?'câu':'từ'}</button><p id="listenStatus" class="muted">Giọng đọc của thiết bị.</p><button class="soft" data-action="listenReveal">${listenShown?'Ẩn':'Xem'} chữ và nghĩa</button>${listenShown?`<div class="feedback">${example?sentence(example):`<p>${hanzi(w.hanzi)} — ${esc(w.meaning)}</p>`}</div>`:''}`:`<p>${esc(quiz.question)}</p><div class="answers">${quiz.choices.map((c,i)=>`<button data-answer="${i}" ${chosen!==null?'disabled':''} class="${chosen!==null&&i===quiz.answer?'correct':chosen===i?'incorrect':''}">${esc(c)}</button>`).join('')}</div>${chosen!==null?`<div class="feedback" role="status"><b>${chosen===quiz.answer?'Đúng.':'Hãy thử nhớ lại.'}</b><p>${esc(quiz.explain)}</p></div><button class="soft" data-action="retryQuiz">Thử lại</button>`:''}`}<p class="muted">${note}</p>`;
 return `<h3>Bạn còn nhớ nghĩa chính không?</h3><p>Nhìn chữ, tự đọc và nhớ nghĩa trước khi xem gợi ý.</p><div class="recall-word">${hanzi(w.hanzi)}</div><button class="soft" data-action="revealReview">${revealed?'Ẩn gợi ý':'Xem nghĩa'}</button>${revealed?`<div class="feedback"><b>${esc(w.meaning)}</b>${example?sentence(example):''}</div>`:''}<div class="grade-buttons"><button data-grade="again">Quên<small>10 phút</small></button><button data-grade="hard">Còn khó<small>1 ngày</small></button><button data-grade="good">Nhớ nghĩa<small>${intervals[Math.min(progress.card(w.id).step,4)]} ngày</small></button></div><p class="muted">Bạn có thể chọn mức nhớ ngay, không bắt buộc mở gợi ý. Đánh giá này hẹn ôn nghĩa, không chứng nhận đã biết dùng từ. ${note}</p>`;
}
function renderStage(){const w=selected;if(auditLesson(w).ready&&(stage<3||(w.lesson.version===2&&stage===3)))return renderStandardLesson(w,{stage,view:lessonView,usageIndex,exampleIndex:standardExampleIndex,trapIndex,checkState,esc,hanzi,rich});if(!['deep','editing'].includes(w.status))return renderFoundation(w);
 if(stage===0)return `<p class="course-word-source">HSK ${w.level} · Mục ${w.sourceIndex} · ${statusLabels[w.status]}</p><span class="eyebrow">01 / HIỂU NGHĨA CHÍNH</span><section class="intro-word"><h3>Giới thiệu từ mới</h3>${w.intro.map((x,i)=>`${i===1?'<details class="other-readings"><summary>Cách đọc khác · trong phần giới thiệu</summary>':''}<p class="intro-reading">${hanzi(w.hanzi)} — <span class="pinyin">${esc(x.pinyin)}</span> — ${rich(x.meaning)}</p>${x.sourcePinyin?`<details class="source-reading"><summary>Cách ghi ở nguồn Hanzii</summary><p class="intro-reading">${esc(x.sourcePinyin)}</p><p class="muted">Bài dùng cách đọc đã đối chiếu với đề cương. Khác biệt có thể liên quan thanh nhẹ, biến điệu hoặc cách ghi.</p></details>`:''}${i>0&&i===w.intro.length-1?'</details>':''}`).join('')}<div class="audio-row"><button class="soft" data-say="${w.hanzi}">◖ Nghe từ trong bài</button><button class="soft" data-say="${w.examples[0].zh}">Nghe trong câu</button></div><p class="muted">Cách đọc đã đối chiếu với đề cương chính thức khi có dữ liệu tương ứng.</p></section><h3>Hình dung tình huống</h3><p>${rich(w.scene)}</p><div class="callout">${rich(w.when)}</div><details><summary>Học thêm · ${w.more.length} mục</summary>${w.more.map(m=>`<h4>${esc(m.title)}</h4><p>${rich(m.text)}</p>`).join('')}</details>`;
 if(stage===1){const ex=w.examples[exampleIndex];return `<span class="eyebrow">02 / GHÉP CÂU</span><h3>Từ đứng ở đâu?</h3><p class="pattern">${rich(w.pattern)}</p><ul>${w.phrases.map(x=>`<li>${rich(x)}</li>`).join('')}</ul><div class="example-card">${sentence(ex)}<div class="card-pager"><button class="soft" data-example="-1" ${exampleIndex===0?'disabled':''} aria-label="Ví dụ trước">←</button><span>Ví dụ ${exampleIndex+1}/${w.examples.length}</span><button class="soft" data-example="1" ${exampleIndex===w.examples.length-1?'disabled':''} aria-label="Ví dụ tiếp">→</button></div></div>${w.forms.length?`<details><summary>Phủ định và câu hỏi</summary>${w.forms.map(s=>`<div class="form-example">${sentence(s)}</div>`).join('')}</details>`:''}`}
 if(stage===2)return `<span class="eyebrow">03 / PHÂN BIỆT</span><div class="trap"><h3>Bẫy thường gặp</h3><p>${rich(w.trap)}</p></div><section class="comparison"><span class="tag">GIỐNG MẶT CHỮ</span><h3>${hanzi(w.shape.pair)}</h3><p>${rich(w.shape.difference)}</p>${w.shape.examples.map(x=>`<p class="contrast-line">${rich(x)}</p>`).join('')}</section><details class="comparison"><summary>Gần nghĩa · ${esc(w.near.pair)}</summary><p>${rich(w.near.difference)}</p>${w.near.examples.map(x=>`<p class="contrast-line">${rich(x)}</p>`).join('')}</details><p class="muted">${rich(w.recognize)} Chạm chữ Hán trong tiêu đề đối chiếu để mở phân tích.</p>`;
 if(stage===3)return practiceHTML();
 return `<span class="eyebrow">05 / TỰ NHỚ VÀ HẸN ÔN</span><h3>Bạn dùng được từ này chưa?</h3><p>Nhìn chữ, tự đọc và nói một câu của bạn trước khi mở gợi ý.</p><div class="recall-word">${hanzi(w.hanzi)}</div><button class="soft" data-action="revealReview">${revealed?'Ẩn gợi ý':'Hiện gợi ý'}</button>${revealed?`<div class="feedback"><b>${esc(w.meaning)}</b><p>${esc(w.task)}</p>${sentence({zh:w.model,vi:'Một câu tham khảo; không phải đáp án duy nhất.'})}</div>`:''}<div class="grade-buttons"><button data-grade="again">Quên<small>10 phút</small></button><button data-grade="hard">Còn khó<small>1 ngày</small></button><button data-grade="good">Đã nhớ<small>${intervals[Math.min(progress.card(w.id).step,4)]} ngày</small></button></div><p class="muted">Bạn có thể chọn mức nhớ ngay, không bắt buộc mở gợi ý. Chỉ đánh dấu đã học khi bạn chọn một mức nhớ. “Từ tiếp theo” chỉ chuyển bài. Lịch gợi ý: 1, 3, 7, 14, 30 ngày.</p>`;
}
function practiceHTML(){const w=selected;return `<span class="eyebrow">04 / THỬ DÙNG</span><div class="practice-tabs" role="group" aria-label="Loại bài luyện"><button class="${quizMode==='choice'?'active':''}" data-mode="choice">Chọn câu</button><button class="${quizMode==='listen'?'active':''}" data-mode="listen">Nghe</button><button class="${quizMode==='self'?'active':''}" data-mode="self">Tự nói / viết</button></div>${quizMode==='choice'?`<h3>${esc(w.quiz.question)}</h3><div class="answers">${w.quiz.choices.map((x,i)=>`<button data-answer="${i}" ${chosen!==null?'disabled':''} class="${chosen!==null&&i===w.quiz.answer?'correct':chosen===i?'incorrect':''}">${esc(x)}</button>`).join('')}</div>${chosen!==null?`<div class="feedback" role="status"><b>${chosen===w.quiz.answer?'Đúng trong tình huống này.':'Hãy nhìn lại sự khác biệt.'}</b><p>${rich(w.quiz.explain)}</p><p>Đáp án: ${esc(w.quiz.choices[w.quiz.answer])}</p></div><button class="soft" data-action="retryQuiz">Thử lại</button>`:''}`:quizMode==='listen'?`<h3>Nghe một câu, nhớ ý chính</h3><p>Chưa nhìn chữ: thử nhắc lại và nói nghĩa bằng tiếng Việt.</p><div class="listen-symbol" aria-hidden="true">◖</div><div class="audio-row"><button class="primary" data-action="listen">Phát câu</button><button class="soft" data-action="listenSlow">Nghe chậm</button></div><p id="listenStatus" class="muted">${heard?'Đã phát xong. Hãy tự nhớ trước khi xem.':'Giọng đọc zh-CN của thiết bị. Nếu chưa nghe được, kiểm tra giọng đọc trước.'}</p><button class="soft" data-action="listenReveal">${listenShown?'Ẩn câu và nghĩa':'Xem câu và nghĩa'}</button>${listenShown?`<div class="feedback">${sentence(w.examples[0])}</div>`:''}`:`<h3>${esc(w.task)}</h3><p>Hãy nói thành tiếng hoặc viết một câu trước khi mở gợi ý.</p><label for="selfAnswer">Câu của bạn (không lưu khi tải lại trang)</label><textarea id="selfAnswer" rows="3" placeholder="Viết bằng chữ Hán…">${esc(drafts.get(w.id)||'')}</textarea><button class="soft" data-action="selfReveal">${revealed?'Ẩn câu tham khảo':'Hiện câu tham khảo'}</button><div id="selfFeedback" ${revealed?'':'hidden'} class="feedback"><p lang="zh-CN">${hanzi(w.model)}</p><p>Đây là một cách trả lời. App chưa tự chấm câu tự viết.</p><ul><li>Câu có đúng ý của tình huống không?</li><li>Từ mục tiêu đứng đúng vị trí chưa?</li><li>Cách ghép có giống mẫu đã học không?</li></ul><p>Khác câu mẫu chưa có nghĩa là sai. Cần phân biệt sai cấu trúc, khác nghĩa, thiếu ngữ cảnh và cách nói vẫn chấp nhận.</p></div>`}`;}
function redrawBody(){stop();$('#lessonBody').innerHTML=coverageNotice(selected)+renderStage()}
function nextWord(){if(pos<session.length-1){openWord(session[pos+1],{queue:session,review:isReview,stage:isReview?4:0})}else{stop();content.innerHTML=`<section class="completion"><span class="complete-glyph">好</span><h2>Đã đi hết lượt này.</h2><p>Những từ đã tự đánh giá được lưu vào lịch ôn. Từ bỏ qua chưa tự đánh dấu đã học.</p><button class="primary" data-action="practiceSession">◇ Thực hành hội thoại bài vừa học</button><button class="soft" data-action="handsfreeSession">◖ Nghe rảnh tay bài vừa học</button><button class="soft" data-action="close">Về danh sách</button></section>`;}}
function closeWord(render=true){stop();dialog.close();document.body.classList.remove('word-open');if(render){if(routeName==='words')home();else if(routeName==='review')review();updateDue()}if(returnFocus?.isConnected)returnFocus.focus()}
function exportProgress(){const blob=new Blob([JSON.stringify(progress.state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='hanzi-viet-tu-vung-tien-do.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function importFile(e){const file=e.target.files[0];if(!file)return;try{if(file.size>5000000)throw Error('Bản sao phải nhỏ hơn 5 MB.');const s=JSON.parse(await file.text());if(!confirm('Thay tiến độ từ vựng hiện tại bằng bản sao này?'))return;progress.replace(s);notify('Đã nhập tiến độ từ vựng.');route()}catch(err){notify(err.message||'Không đọc được file.')}finally{e.target.value=''}}
document.addEventListener('input',e=>{if(e.target.dataset.v2Draft&&selected)checkState.set(selected.id+':draft:'+e.target.dataset.v2Draft,e.target.value);if(e.target.id==='selfAnswer'&&selected)drafts.set(selected.id,e.target.value)});
document.addEventListener('click',e=>{
 const button=e.target.closest('button');if(!button||button.disabled||!dataset)return;const d=button.dataset;
 if(d.auditPage){auditPage+=Number(d.auditPage);renderAuditList();return}
 if(d.v2Hint){const key=selected.id+':hint:'+d.v2Hint;checkState.set(key,Math.min(3,(checkState.get(key)||0)+1));redrawBody();return}
 if(d.v2Unlock){checkState.set(selected.id+':self-unlocked',true);redrawBody();return}
 if(d.lessonView){lessonView=d.lessonView;redrawBody();return}
 if(d.lessonPage){const key=d.lessonPage,total=key==='usage'?selected.lesson.usages.length:key==='example'?selected.lesson.examples.length:selected.lesson.traps.length,delta=Number(d.delta);if(key==='usage')usageIndex=Math.max(0,Math.min(total-1,usageIndex+delta));else if(key==='example')standardExampleIndex=Math.max(0,Math.min(total-1,standardExampleIndex+delta));else trapIndex=Math.max(0,Math.min(total-1,trapIndex+delta));redrawBody();return}
 if(d.lessonStop){stop();return}
 if(d.lessonAudio){playLessonSegments(lessonAudio(selected,d.lessonAudio,Number(d.lessonIndex||0)));return}
 if(d.standardCheck){checkState.set(selected.id+':'+d.standardCheck,Number(d.checkChoice));redrawBody();return}
 if(d.revealCheck){checkState.set(selected.id+':'+d.revealCheck,'requested');redrawBody();return}
 if(d.checkQuestionAudio){playLessonSegments(checkAudio(selected,d.checkQuestionAudio,'question'));return}
 if(d.checkAnswerAudio){playLessonSegments(checkAudio(selected,d.checkAnswerAudio,'answer',{revealed:checkState.has(selected.id+':'+d.checkAnswerAudio)}));return}

 if(d.level){courseLevel=Number(d.level);lessonPage=0;query='';filter='all';try{storage.setItem('hanzi-course-level-v7',String(courseLevel))}catch{}home();return}
 if(d.start){const target=words.find(w=>w.id===d.start);if(target&&target.level!==courseLevel){courseLevel=target.level;query='';filter='all';lessonPage=0}if(d.resume){const i=coursePages(dataset,filtered()).findIndex(l=>l.wordIds.includes(d.start));if(i>=0)lessonPage=i}const resume=d.resume&&progress.state.last?.id===d.start?progress.state.last.stage:0;openWord(d.start,{stage:resume});return}
 if(d.filter){filter=d.filter;lessonPage=0;home();return}
 if(d.lesson){lessonPage+=Number(d.lesson);renderList();return}
 if(d.player){handlePlayer(d.player);return}
 if(d.say){speak(d.say,!!d.slow);return}
 if(d.step!==undefined){stage=Number(d.step);revealed=false;drawWord();$('#vstep-'+stage).focus();return}
 if(d.example){exampleIndex=Math.max(0,Math.min(selected.examples.length-1,exampleIndex+Number(d.example)));redrawBody();return}
 if(d.mode){quizMode=d.mode;revealed=false;listenShown=false;drawWord();return}
 if(d.answer!==undefined){if(e.target.closest('a'))return;chosen=Number(d.answer);redrawBody();return}
 if(d.grade){progress.grade(selected.id,d.grade);notify('Đã lưu '+selected.hanzi+' · '+(d.grade==='again'?'Ôn lại sau 10 phút':d.grade==='hard'?'Ôn lại sau 1 ngày':'Đã cập nhật lịch ôn'));updateDue();nextWord();return}
 switch(d.action){case'podcastReady':audioOptions.scope='ready';$('#audioScope').value='ready';$('#audioLessonRow').hidden=true;$('#audioRangeRow').hidden=true;loadAudioPlan();break;case'audit':location.hash='audit';break;case'retryPractice':practiceView();break;case'practiceLesson':openPractice(lessonWords().map(w=>w.id));break;case'practiceSession':openPractice(session);break;case'handsfree':openHandsfree(lessonWords());break;case'handsfreeSession':openHandsfree(session.map(id=>words.find(w=>w.id===id)).filter(Boolean));break;case'studyLesson':{const list=lessonWords();if(list.length)openWord(list[0].id,{queue:list.map(w=>w.id)});break}case'close':closeWord();break;case'next':if(stage<4){stage=moveStep(selected,stage,1);revealed=false;drawWord()}else nextWord();break;case'back':if(stage>0){stage=moveStep(selected,stage,-1);revealed=false;drawWord()}else if(pos>0)openWord(session[pos-1],{queue:session,review:isReview});break;case'skip':nextWord();break;case'favorite':progress.favorite(selected.id);button.textContent=progress.card(selected.id).favorite?'★':'☆';button.setAttribute('aria-pressed',progress.card(selected.id).favorite);button.setAttribute('aria-label',progress.card(selected.id).favorite?'Bỏ yêu thích':'Yêu thích');break;case'retryQuiz':chosen=null;redrawBody();break;case'listen':speak(selected.examples[0]?.zh||selected.audioText||selected.hanzi);break;case'listenSlow':speak(selected.examples[0]?.zh||selected.audioText||selected.hanzi,true);break;case'listenReveal':listenShown=!listenShown;drawWord();break;case'selfReveal':revealed=!revealed;$('#selfFeedback').hidden=!revealed;button.textContent=revealed?'Ẩn câu tham khảo':'Hiện câu tham khảo';break;case'revealReview':revealed=!revealed;redrawBody();break;case'reviewDue':{const list=progress.due(words);if(list.length)openWord(list[0].id,{queue:list.map(w=>w.id),review:true,stage:4});else review();break}case'practiceLearned':{const list=words.filter(w=>progress.card(w.id).learned);if(!list.length){notify('Chưa có từ đã học. Hãy tự đánh giá ở bước Ôn trước.');break}openWord(list[0].id,{queue:list.map(w=>w.id),review:true,stage:4});break}case'refresh':route();break;case'export':exportProgress();break;case'import':$('#vocabImport').click();break;}
});
dialog.addEventListener('cancel',e=>{e.preventDefault();closeWord()});
dialog.addEventListener('keydown',e=>{if(!e.target.closest('[data-step]')||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const steps=studySteps(selected);stage=e.key==='Home'?steps[0]:e.key==='End'?steps.at(-1):steps[(steps.indexOf(stage)+(e.key==='ArrowRight'?1:-1)+steps.length)%steps.length];revealed=false;drawWord();$('#vstep-'+stage).focus()});
window.addEventListener('hashchange',()=>dataset&&route());window.addEventListener('pagehide',()=>{stop();releaseWake()});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')keepAwake()});
function openPractice(ids){practiceIds=[...ids];if(dialog.open)closeWord(false);if(location.hash==='#practice')route();else location.hash='practice'}
async function practiceView(){
 const token=++practiceSerial;main.innerHTML='<section class="panel"><h1>Đang mở hội thoại…</h1><p>Chuẩn bị tình huống, lời thoại và phần thực hành.</p></section>';
 try{const module=await import('./conversation.js?v=8.0.0');const params=new URLSearchParams(location.search);const controller=await module.mountConversations(main,{words,lessonIds:practiceIds,notify,stopOthers:()=>{player.stop();oneShot.stop()},isActive:()=>routeName==='practice'&&token===practiceSerial,initialId:params.get('conversation'),initialTurn:Number(params.get('turn')||0)});if(routeName==='practice'&&token===practiceSerial)conversationController=controller;else controller.destroy()}
 catch(e){if(routeName==='practice'&&token===practiceSerial)main.innerHTML=`<section class="panel"><h1>Chưa mở được hội thoại</h1><p>${esc(e.message)}</p><p>Kiểm tra js/conversation.js và data/vocabulary/conversations-demo.json.</p><button class="soft" data-action="retryPractice">Thử lại</button></section>`}
}

let selectedAudioIds=[];
function audioWords(){if(audioOptions.scope==='selection')return selectedAudioIds.map(id=>words.find(w=>w.id===id)).filter(Boolean);if(audioOptions.scope==='lesson')return(dataset.lessons[audioOptions.lesson]?.wordIds||[]).map(id=>words.find(w=>w.id===id)).filter(Boolean);return selectAudioWords(words,audioOptions,id=>progress.card(id))}
function openHandsfree(list){selectedAudioIds=list.map(w=>w.id);audioOptions.scope='selection';if(dialog.open)closeWord(false);if(location.hash==='#audio')route();else location.hash='audio'}
function audioView(){
 const lessons=dataset.lessons;
 main.innerHTML=`<section class="audio-heading"><span class="eyebrow">NGHE RẢNH TAY</span><h1>Chọn nhịp nghe của bạn.</h1><p>Tự chuyển từ và câu. Không cần dừng để làm bài tập.</p></section><div class="audio-mode-grid" role="radiogroup" aria-label="Chế độ nghe">${audioModes.map((m,i)=>`<label class="mode-card ${audioOptions.mode===m.id?'selected':''}"><input type="radio" name="audioMode" value="${m.id}" ${audioOptions.mode===m.id?'checked':''}><span class="mode-icon">${m.icon}</span><b>${i+1} · ${m.title}</b><small>${m.description}</small></label>`).join('')}</div><section class="audio-scope panel"><h2>Phạm vi nghe</h2><label for="audioScope">Chọn các từ</label><select id="audioScope">${selectedAudioIds.length?'<option value="selection">Bài / nhóm vừa chọn</option>':''}<option value="ready">Chỉ bài học đầy đủ</option><option value="lesson">Một bài 24 từ</option><option value="all">Cả ${words.length.toLocaleString('vi-VN')} mục từ · HSK 1–3</option><option value="favorite">Chỉ từ yêu thích</option><option value="new">Chỉ từ chưa học</option><option value="learned">Chỉ từ đã học</option><option value="range">Từ số… đến số…</option></select><div id="audioLessonRow" class="scope-extra" ${audioOptions.scope==='lesson'?'':'hidden'}><label for="audioLesson">Bài muốn nghe</label><select id="audioLesson">${lessons.map((l,i)=>`<option value="${i}">${esc(l.title)} · ${l.wordIds.length}/24 từ</option>`).join('')}</select></div><div id="audioRangeRow" class="scope-extra range-inputs" ${audioOptions.scope==='range'?'':'hidden'}><label>Từ số<input id="audioFrom" type="number" min="1" max="${words.length}" value="${audioOptions.from}"></label><label>Đến số<input id="audioTo" type="number" min="1" max="${words.length}" value="${audioOptions.to}"></label></div><p id="audioCount" class="scope-count"></p><button id="podcastReady" class="soft" data-action="podcastReady" hidden>Nghe các mục đủ mẫu hiện có</button></section><section class="player-panel" aria-label="Trình phát nghe rảnh tay"><div class="player-meta"><span id="playerState" role="status" aria-live="polite">Sẵn sàng</span><span id="playerCount"></span></div><div id="playerWord" class="player-word" lang="zh-CN">◖</div><p id="playerSegment" class="player-segment">Chọn chế độ, rồi bấm Bắt đầu nghe.</p><p id="playerText" class="player-text"></p><progress id="audioProgress" value="0" max="1" aria-label="Tiến độ phát"></progress><div class="player-controls"><button class="soft" data-player="previous" aria-label="Nghe từ trước">←</button><button class="primary" id="audioPlay" data-player="play">Bắt đầu nghe</button><button class="soft" data-player="next" aria-label="Nghe từ tiếp">→</button><button class="soft" data-player="stop" aria-label="Dừng và về đầu">■</button></div><label class="rate-label" for="audioRate">Tốc độ <output id="rateValue">${audioOptions.rate.toFixed(2)}×</output></label><input id="audioRate" type="range" min="0.5" max="1.5" step="0.05" value="${audioOptions.rate}"><div class="player-options"><label><input id="audioRepeat" type="checkbox" ${audioOptions.repeat?'checked':''}> Lặp lại phạm vi</label><label><input id="audioAwake" type="checkbox" ${audioOptions.awake?'checked':''}> Giữ màn hình sáng</label></div><p id="wakeStatus" class="muted"></p><p class="audio-caveat">Giọng đọc trên thiết bị: Trung phổ thông và tiếng Việt. Khi khóa màn hình hoặc đổi ứng dụng, trình duyệt có thể ngắt tiếng. “Giữ màn hình sáng” hoạt động khi thiết bị hỗ trợ.</p></section><section class="panel voice-check"><h2>Giọng đọc · Bản sửa 5.1</h2><p id="voiceStatus">Đang kiểm tra giọng đọc…</p><div class="voice-selectors"><label for="zhVoice">Giọng Trung phổ thông</label><select id="zhVoice"></select><label for="viVoice">Giọng tiếng Việt</label><select id="viVoice"></select></div><p id="voiceTestStatus" role="status" class="muted">Bấm từng nút để kiểm tra âm thanh thực tế.</p><div class="button-row"><button class="soft" data-player="testZh">Thử giọng Trung</button><button class="soft" data-player="testVi">Thử giọng Việt</button></div><p>Ôn nhanh đọc từ và nghĩa. Ngấm ngữ cảnh thêm giải thích ngắn và ví dụ. Podcast chỉ phát mục đủ mẫu mới: phần nghĩa, cách dùng, ví dụ, bẫy và hướng dẫn đọc. Câu hỏi và lời giải được mở riêng. Tắm ngôn ngữ chỉ phát chữ Hán.</p><p>Tạm dừng sẽ dừng đoạn hiện tại; Tiếp tục đọc lại đầu đoạn đó để tránh bỏ mất lời. Thay tốc độ khi đang nghe cũng đọc lại đoạn hiện tại. Đổi chế độ hoặc phạm vi sẽ dừng và về đầu.</p><p>Nghe không tự đánh dấu đã học. Hãy tự đánh giá trong bài học để tạo lịch ôn.</p><details><summary>Nếu điện thoại chưa phát được tiếng</summary><ol><li>Mở trang trực tiếp bằng Chrome.</li><li>Vào Cài đặt điện thoại, tìm “Chuyển văn bản thành giọng nói” hoặc “Text-to-speech”.</li><li>Chọn bộ đọc Google nếu có; mở cài đặt bộ đọc và cài dữ liệu tiếng Trung (Trung Quốc) và tiếng Việt.</li><li>Trở lại Chrome, tải lại trang rồi thử từng giọng.</li></ol><p><a href="https://support.google.com/accessibility/android/answer/6006983?hl=vi" target="_blank" rel="noopener">Hướng dẫn cài giọng của Google ↗</a></p><p>Nếu còn lỗi, gửi lại dòng có [Mã: …] trong app. Không cần xóa tiến độ.</p></details></section>`;
 $('#audioScope').value=audioOptions.scope;$('#audioLesson').value=audioOptions.lesson;
 document.querySelectorAll('[name="audioMode"]').forEach(input=>input.addEventListener('change',()=>{audioOptions.mode=input.value;document.querySelectorAll('.mode-card').forEach(label=>label.classList.toggle('selected',label.contains(input)));loadAudioPlan()}));
 $('#audioScope').addEventListener('change',e=>{audioOptions.scope=e.target.value;$('#audioLessonRow').hidden=audioOptions.scope!=='lesson';$('#audioRangeRow').hidden=audioOptions.scope!=='range';loadAudioPlan()});
 $('#audioLesson').addEventListener('change',e=>{audioOptions.lesson=Number(e.target.value);loadAudioPlan()});
 for(const [id,key] of [['audioFrom','from'],['audioTo','to']])$('#'+id).addEventListener('input',e=>{audioOptions[key]=Number(e.target.value);loadAudioPlan()});
 $('#audioRate').addEventListener('input',e=>{audioOptions.rate=Number(e.target.value);$('#rateValue').value=audioOptions.rate.toFixed(2)+'×';player.setRate(audioOptions.rate)});
 $('#audioRepeat').addEventListener('change',e=>{audioOptions.repeat=e.target.checked;player.setRepeat(audioOptions.repeat)});
 $('#audioAwake').addEventListener('change',e=>{audioOptions.awake=e.target.checked;if(audioOptions.awake)keepAwake();else releaseWake()});
 loadAudioPlan();showVoices();
}
function loadAudioPlan(){
 let valid=true;if(audioOptions.scope==='range')valid=Number.isInteger(audioOptions.from)&&Number.isInteger(audioOptions.to)&&audioOptions.from>=1&&audioOptions.to<=words.length&&audioOptions.to>=audioOptions.from;
 const list=valid?audioWords():[];const plan=buildPlaylist(list,audioOptions.mode);player.load(plan);player.setRate(audioOptions.rate);player.setRepeat(audioOptions.repeat);
 if($('#audioCount'))$('#audioCount').textContent=!valid?'Nhập số đầu và cuối trong khoảng 1–'+words.length+', số đầu không lớn hơn số cuối.':list.length?list.length+' từ · '+plan.length+' đoạn đọc · '+audioModes.find(m=>m.id===audioOptions.mode).title:'Phạm vi chưa có từ. Chọn phạm vi khác hoặc thêm yêu thích / học từ trước.';
 if($('#audioCount')&&list.some(w=>w.status!=='deep'))$('#audioCount').textContent+=' · Thẻ tra cứu chỉ đọc từ và nghĩa; thẻ có ví dụ thêm câu; Podcast đủ phần giảng chỉ ở bài chi tiết.';
 if(audioOptions.mode==='podcast'&&$('#audioCount'))$('#audioCount').textContent=new Set(plan.map(s=>s.wordId)).size+' mục đủ mẫu có lời giảng · '+(list.length-new Set(plan.map(s=>s.wordId)).size)+' mục chưa đủ mẫu được bỏ qua. Có thể chọn phạm vi Chỉ bài học đầy đủ.';
 if($('#podcastReady'))$('#podcastReady').hidden=audioOptions.mode!=='podcast'||list.every(w=>auditLesson(w).ready);
 if($('#audioPlay'))$('#audioPlay').disabled=!plan.length;
}
function updatePlayerUI(s){
 const dock=$('#listeningDock');if(dock){dock.hidden=routeName!=='audio'||!['playing','paused'].includes(s.status);if(!dock.hidden){$('#dockWord').textContent=s.item?.word||'';$('#dockPlay').textContent=s.status==='playing'?'Tạm dừng':'Tiếp tục';}}
 if(!$('#playerState'))return;
 const labels={idle:'Sẵn sàng',playing:'Đang phát',paused:'Đã tạm dừng',completed:'Đã nghe hết',error:'Chưa phát được giọng đọc'};
 $('#playerState').textContent=labels[s.status];$('#audioPlay').textContent=s.status==='playing'?'Tạm dừng':s.status==='paused'?'Tiếp tục':s.status==='completed'?'Nghe lại từ đầu':'Bắt đầu nghe';
 const item=s.item;$('#playerWord').textContent=item?.word||'◖';$('#playerCount').textContent=item?'Từ '+(item.wordIndex+1)+'/'+new Set(s.queue.map(x=>x.wordId)).size:'';$('#playerSegment').textContent=item?.label||'Chọn phạm vi để bắt đầu.';$('#playerText').textContent=item?.text||'';$('#audioProgress').max=Math.max(1,s.total);$('#audioProgress').value=s.status==='completed'?s.total:s.index;
 const currentWord=item?.wordIndex||0,lastWord=s.queue.at(-1)?.wordIndex||0;document.querySelector('[data-player="previous"]').disabled=!s.total||currentWord===0;document.querySelector('[data-player="next"]').disabled=!s.total||currentWord===lastWord;
 if(s.status==='error'){$('#playerText').textContent=speechErrorMessage(s.error);}
 if($('#wakeStatus'))$('#wakeStatus').textContent=wakeLock?'Đang giữ màn hình sáng.':s.status==='playing'&&audioOptions.awake?'Đang yêu cầu giữ màn hình sáng…':'';
}
function showVoices(){
 if(!$('#voiceStatus'))return;const voices=window.speechSynthesis?.getVoices()||[];
 for(const [id,lang] of [['zhVoice','zh-CN'],['viVoice','vi-VN']]){
  const select=$('#'+id),list=voices.filter(v=>voiceMatches(v,lang));
  select.innerHTML='<option value="">Tự động · để hệ thống chọn theo ngôn ngữ</option>'+list.map(v=>`<option value="${esc(v.voiceURI)}">${esc(v.name)} · ${esc(v.lang)}</option>`).join('');
  select.value=list.some(v=>v.voiceURI===voicePreferences[lang])?voicePreferences[lang]:'';
  select.onchange=()=>{stop();voicePreferences[lang]=select.value;try{storage.setItem('hanzi-viet-voices-v51',JSON.stringify(voicePreferences))}catch{};$('#voiceTestStatus').textContent='Đã đổi giọng. Bấm Thử giọng để kiểm tra.'};
 }
 const zh=voices.filter(v=>voiceMatches(v,'zh-CN')),vi=voices.filter(v=>voiceMatches(v,'vi-VN'));
 $('#voiceStatus').textContent='Trình duyệt đang liệt kê '+zh.length+' giọng Trung phổ thông và '+vi.length+' giọng Việt. Danh sách có thể tải chậm; nếu chưa liệt kê giọng, chế độ Tự động vẫn gửi yêu cầu đúng ngôn ngữ cho hệ thống.';
}
function handlePlayer(action){
 if(action==='play'){oneShot.stop();if(player.state.status==='playing')player.pause();else{player.play();keepAwake()}return}
 if(action==='stop'){stop();return}if(action==='previous'){oneShot.stop();player.moveWord(-1);return}if(action==='next'){oneShot.stop();player.moveWord(1);return}
 if(action==='testZh'||action==='testVi'){const lang=action==='testZh'?'zh-CN':'vi-VN';speak(lang==='zh-CN'?'我想学习汉语。':'Xin chào. Đây là giọng tiếng Việt.',false,lang);}
}
window.speechSynthesis?.addEventListener('voiceschanged',showVoices);
document.addEventListener('change',e=>{const key=e.target.dataset.display;if(!key)return;display[key]=e.target.checked;if(!Object.values(display).some(Boolean)){display[key]=true;e.target.checked=true;notify('Giữ ít nhất một mục hiển thị để chọn được từ.');return}saveDisplay();renderList()});

async function boot(){try{const r=await fetch('./data/vocabulary/hanzii-course.json?v=batch-047');if(!r.ok)throw Error('Thiếu file data/vocabulary/hanzii-course.json.');dataset=validateCourse(await r.json());words=dataset.words;audioOptions.to=words.length;const p=new URLSearchParams(location.search),id=p.get('word'),saved=words.find(w=>w.id===id),step=Number(p.get('step')||0);if(saved)courseLevel=saved.level;route();if(saved){lessonPage=coursePages(dataset,filtered()).findIndex(l=>l.wordIds.includes(saved.id));openWord(saved.id,{stage:step,queue:lessonWords().map(w=>w.id)})}else if(id)notify('Từ được liên kết chưa có trong khóa học.')}catch(err){main.innerHTML=`<section class="panel"><h1>Chưa mở được bài học</h1><p>${esc(err.message)}</p><p>Hãy mở qua địa chỉ GitHub Pages, không mở file HTML trực tiếp.</p><button class="primary" id="retryLoad">Thử lại</button></section>`;$('#retryLoad').onclick=()=>location.reload()}}
boot();

